package com.example.paymentservice.entity;

import jakarta.persistence.*;
import lombok.Data;
import java.time.LocalDateTime;

@Entity
@Table(name = "payments")
@Data
public class Payment {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String paymentId;
    private double amount;

    @Enumerated(EnumType.STRING)
    private PaymentStatus status;

    private String orderIds; // Comma-separated list of order IDs
    private String paymentMethod;
    private String failureReason;
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    @PrePersist
    protected void onCreate() {
        createdAt = LocalDateTime.now();
        updatedAt = LocalDateTime.now();
    }

    @PreUpdate
    protected void onUpdate() {
        updatedAt = LocalDateTime.now();
    }
}

package com.example.paymentservice.repository;

import com.example.paymentservice.entity.Payment;
import org.springframework.data.jpa.repository.JpaRepository;
import java.util.Optional;

public interface PaymentRepository extends JpaRepository<Payment, Long> {
    Optional<Payment> findByPaymentId(String paymentId);
}

package com.example.paymentservice.service;

import com.example.paymentservice.dto.MomoCreatePaymentRequest;
import com.example.paymentservice.dto.MomoPaymentResponse;
import com.example.paymentservice.dto.MomoWebhookRequest;
import com.example.paymentservice.entity.Payment;
import com.example.paymentservice.entity.PaymentStatus;
import com.example.paymentservice.repository.PaymentRepository;
import com.example.paymentservice.client.OrderServiceClient;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Arrays;
import java.util.UUID;

@Service
@RequiredArgsConstructor
public class MomoPaymentService {

    @Value("${momo.partner-code}")
    private String partnerCode;

    @Value("${momo.access-key}")
    private String accessKey;

    @Value("${momo.secret-key}")
    private String secretKey;

    private final PaymentRepository paymentRepository;
    private final OrderServiceClient orderServiceClient;
    private final KafkaTemplate<String, String> kafkaTemplate;

    @Transactional
    public MomoPaymentResponse createPayment(MomoCreatePaymentRequest request) {
        // Create a new payment record
        Payment payment = new Payment();
        payment.setPaymentId(UUID.randomUUID().toString());
        payment.setAmount(Double.parseDouble(request.getAmount()));
        payment.setStatus(PaymentStatus.PENDING);
        payment.setOrderIds(request.getPayeeNote()); // Store comma-separated order IDs
        payment.setPaymentMethod("MOMO");
        paymentRepository.save(payment);

        // Generate QR code using Momo API (simplified version)
        String qrCode = generateMomoQRCode(payment.getPaymentId(), request);

        MomoPaymentResponse response = new MomoPaymentResponse();
        response.setPaymentId(payment.getPaymentId());
        response.setStatus(payment.getStatus().toString());
        response.setAmount(request.getAmount());
        response.setQrCode(qrCode);
        response.setOrderIds(request.getPayeeNote().split(","));

        return response;
    }

    private String generateMomoQRCode(String paymentId, MomoCreatePaymentRequest request) {
        // Implementation would include actual Momo API integration
        // This is a placeholder for the QR code generation logic
        return "momo://pay?paymentId=" + paymentId + "&amount=" + request.getAmount();
    }

    public MomoPaymentResponse getPaymentStatus(String paymentId) {
        Payment payment = paymentRepository.findByPaymentId(paymentId)
                .orElseThrow(() -> new RuntimeException("Payment not found"));

        MomoPaymentResponse response = new MomoPaymentResponse();
        response.setPaymentId(payment.getPaymentId());
        response.setStatus(payment.getStatus().toString());
        response.setAmount(String.valueOf(payment.getAmount()));
        response.setOrderIds(payment.getOrderIds().split(","));

        return response;
    }

    @Transactional
    public void processWebhook(MomoWebhookRequest request) {
        if (!verifyMomoSignature(request)) {
            throw new RuntimeException("Invalid signature");
        }

        Payment payment = paymentRepository.findByPaymentId(request.getPaymentId())
                .orElseThrow(() -> new RuntimeException("Payment not found"));

        if (request.getResultCode() == 0) {
            payment.setStatus(PaymentStatus.SUCCESS);
            // Update all related orders
            Arrays.stream(payment.getOrderIds().split(","))
                    .forEach(orderId -> {
                        orderServiceClient.updateOrderStatus(orderId, "PAID");
                        // Notify through Kafka
                        kafkaTemplate.send("payment-status", orderId, "PAID");
                    });
        } else {
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason(request.getMessage());
            Arrays.stream(payment.getOrderIds().split(","))
                    .forEach(orderId -> {
                        orderServiceClient.updateOrderStatus(orderId, "PAYMENT_FAILED");
                        kafkaTemplate.send("payment-status", orderId, "FAILED");
                    });
        }

        paymentRepository.save(payment);
    }

    private boolean verifyMomoSignature(MomoWebhookRequest request) {
        // Implementation would include actual signature verification
        // This is a placeholder for the signature verification logic
        return true;
    }
}
